<script setup lang="ts">
import {addRowOnEnter} from './entryRows';
import {useAccountingPermissions} from './permissions';
const can=useAccountingPermissions();
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AdminDialog from '../../AdminDialog.vue';
import AccountingSelect from './AccountingSelect.vue';
const props=defineProps<{entryId:number;company:number;accounts:any[];csrf?:string}>();
const emit=defineEmits(['close','saved']);
const data=ref<any>(null),form=ref<any>({}),loading=ref(false),busy=ref(false),error=ref('');
let generation=0;
const cents=(value:any)=>{const text=String(value??'');const match=text.match(/^(-?)(\d{1,12})(?:\.(\d{1,2}))?$/);return match?(Number(match[2])*100+Number((match[3]||'').padEnd(2,'0')))*(match[1]?-1:1):NaN;};
const money=(minor:number)=>Number.isFinite(minor)?(minor/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const accounts=computed(()=>props.accounts.filter(a=>!a.is_group&&a.active&&['Income','Expense'].includes(a.root_type)));
const net=computed(()=>cents(data.value?.net_cash||'0.00'));
const represented=computed(()=>{if(form.value.decision==='outside')return net.value;return (form.value.allocations||[]).reduce((sum:number,line:any)=>{const a=props.accounts.find(a=>a.id===Number(line.account_id));return sum+cents(line.amount)*(line.refund?-1:1)*(a?.root_type==='Income'?1:-1);},0)+cents(form.value.outside_amount||'0.00')*Math.sign(net.value);});
const difference=computed(()=>net.value-represented.value);
async function api(body?:any){const r=await fetch('/accounting/api/cash-basis-reviews/'+props.entryId+(body?'':'?company_id='+props.company),{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to review this entry.');return result;}
async function load(){const gen=++generation;loading.value=true;error.value='';data.value=null;try{const result=await api();if(gen!==generation)return;data.value=result;form.value={...result.review,allocations:result.review.allocations.length?result.review.allocations:[{account_id:'',amount:String(result.net_cash).replace('-',''),refund:false}]};}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>[props.entryId,props.company],()=>void load(),{immediate:true});onBeforeUnmount(()=>generation++);
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api({company_id:props.company,version:form.value.version,decision:form.value.decision,note:form.value.note,outside_amount:form.value.decision==='outside'?'0.00':form.value.outside_amount,allocations:form.value.decision==='outside'?[]:form.value.allocations});emit('saved',result.message);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><AdminDialog title="Cash-basis review" :subtitle="data?.journal.number" :busy="busy" dialog-class="ac-dialog ac-review-dialog" @close="!busy&&emit('close')"><p v-if="loading" role="status">Loading journal and review details...</p><p v-if="error" role="alert" class="notice admin-error">{{error}}</p><template v-if="data"><div class="ac-review-summary"><div><small>Journal date</small><strong>{{data.journal.posting_date}}</strong></div><div><small>{{net<0?'Net cash paid':'Net cash received'}}</small><strong>{{data.currency}} {{money(Math.abs(net))}}</strong></div></div><p>{{data.journal.remarks||'No description recorded.'}}</p><p v-if="data.selected_number!==data.journal.number||data.journal.reversal_id" class="ac-help">This review classifies original entry {{data.journal.number}}. Its reversal automatically offsets the allocation on the reversal date.</p>
<details open><summary>Original journal details</summary><div class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Account</th><th class="numeric">Debit</th><th class="numeric">Credit</th></tr></thead><tbody><tr v-for="line in data.journal.lines" :key="line.id"><td>{{line.account_code}} — {{line.account_name}}</td><td class="numeric">{{money(cents(line.debit))}}</td><td class="numeric">{{money(cents(line.credit))}}</td></tr></tbody></table></div></details>
<p v-if="!data.can_resolve" class="ac-help">{{data.period_locked?'This entry belongs to a locked accounting period. Its reporting allocation cannot be changed.':'Read-only access. An Accounting Manager or Accountant can resolve this entry.'}}</p><p v-if="form.reviewed_by" class="ac-help">Previously reviewed by {{form.reviewed_by}}.</p>
<form @submit.prevent="save"><fieldset class="ac-journal-fields" :disabled="busy||!data.can_resolve"><label>How should this cash movement appear in Profit and Loss?<AccountingSelect><select aria-label="Cash-basis treatment" v-model="form.decision" required><option value="" disabled>Choose treatment</option><option value="allocate">Allocate to income or expense</option><option value="outside">Outside Profit and Loss (loan, advance or transfer)</option></select></AccountingSelect></label>
<template v-if="form.decision==='allocate'"><p class="ac-help">Choose the income or expense account for each part. Use the refund option when reducing an income or expense amount.</p><div v-for="(line,index) in form.allocations" :key="index" @keydown.enter="addRowOnEnter($event,index,form.allocations,()=>({account_id:'',amount:'',refund:false}),!!data?.can_resolve&&!busy)" class="ac-review-allocation"><label>Income / expense account<AccountingSelect><select v-model.number="line.account_id" :aria-label="'Allocation account '+(index+1)" required><option value="" disabled>Select account</option><option v-if="line.account_id&&!accounts.some(a=>a.id===line.account_id)" :value="line.account_id">{{props.accounts.find(a=>a.id===line.account_id)?.name||'Previously selected account'}}</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select></AccountingSelect></label><label>Amount<input v-model="line.amount" :aria-label="'Allocation amount '+(index+1)" inputmode="decimal" pattern="[0-9]{1,10}(\.[0-9]{1,2})?" required></label><label class="ac-check"><input v-model="line.refund" type="checkbox">Refund / reduction</label><button type="button" class="button ac-danger" :aria-label="'Remove allocation '+(index+1)" :disabled="form.allocations.length<=1" @click="form.allocations.splice(index,1)">&times;</button></div><button type="button" class="button" :disabled="form.allocations.length>=100" @click="form.allocations.push({account_id:'',amount:'',refund:false})">+ Add allocation</button><label>Other amount outside Profit and Loss<input aria-label="Other amount outside Profit and Loss" v-model="form.outside_amount" inputmode="decimal" pattern="[0-9]{1,10}(\.[0-9]{1,2})?" required><small>For any remaining loan, advance or other balance-sheet amount in this cash movement.</small></label><p :class="difference===0?'ac-success':'ac-danger'">{{difference===0?'Allocations match the cash movement.':'Unreconciled difference: '+data.currency+' '+money(difference)}}</p></template>
<p v-if="form.decision==='outside'" class="ac-help">The full {{data.currency}} {{money(Math.abs(net))}} cash movement will be classified outside income and expenses for cash-basis reporting.</p><label>Reason / explanation<textarea v-model="form.note" aria-label="Review reason" required minlength="5" maxlength="2000" rows="3" placeholder="Explain the account allocation or why this is outside Profit and Loss"></textarea></label></fieldset><p class="muted ac-stage-note">Saving records a cash-basis reporting allocation and its audit history. Original journal entries and accrual-basis figures remain as posted.</p><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="emit('close')">Close</button><button v-if="data.can_resolve" class="button primary" :disabled="busy||!form.decision||(form.decision==='allocate'&&difference!==0)"><span v-if="busy" class="ac-spinner"></span>{{busy?'Saving...':'Save review'}}</button></div></form></template></AdminDialog></template>
